/// <summary>
/// MPJ_5012_RebateProcess
/// Class <c>METGUPPRiceDiscPricingRulePreviewExcludeFormControl_Extension</c>
/// </summary>
[ExtensionOf(formControlStr(GUPPRiceDiscPricingRulePreview, METExcludeForPaymentBtn))]
internal final class METGUPPRiceDiscPricingRulePreviewExcludeFormControl_Extension
{
}

Method.Source:
    /// <summary>
    /// Excluding the selected products from payment
    /// </summary>
    public void clicked()
    {
        next clicked();

        MultiSelectionHelper    selectionHelper = MultiSelectionHelper::construct();
        InventTable             inventTableExclusion;
        
        FormDataSource  inventTable_ds  = this.formRun().dataSource(formDataSourceStr(GUPPriceDiscPricingRulePreview, InventTable)) as FormDataSource;
        selectionHelper.parmDatasource(InventTable_ds);
        inventTableExclusion = selectionHelper.getFirst();
        GUPRefRecId ruleId = this.getRuleId(element.args());

        ttsbegin;
        while (inventTableExclusion)
        {
            METExcludeForPaymentProducts    excludeForPaymentProducts;
            excludeForPaymentProducts.initValue();
            excludeForPaymentProducts.addToExcludeForPayment(ruleId, inventTableExclusion.ItemId);
            inventTableExclusion = selectionHelper.getNext();
        }
        ttscommit;
    
        InventTable_ds.executeQuery();

    }

public GUPRefRecId getRuleId(Args    _args)
{
    GUPPricingRulePreviewTrans pricingRulePreviewTrans = _args.record() as GUPPricingRulePreviewTrans;
    return GUPPricingRuleCopy::findByRuleId(pricingRulePreviewTrans.PricingRuleLine).RuleId;
}
